SELECT TO_DATE('27-10-2026','DD-MM-YYYY') - SYSDATE FROM DUAL;
-- 0.395833333
SELECT ROUND(TO_DATE('27-10-2026','DD-MM-YYYY') - SYSDATE) FROM DUAL;
