SELECT (TO_DATE('25-08-2026','DD-MM-YYYY') - TO_DATE('26-08-1996','DD-MM-YYYY')) / 365 FROM DUAL;
-- 30.0164384
SELECT MONTHS_BETWEEN(TO_DATE('25-08-2026','DD-MM-YYYY'), TO_DATE('26-08-1996','DD-MM-YYYY')) / 12 FROM DUAL;
-- 29.9973118

SELECT NEXT_DAY(TO_DATE('25-10-2026','DD-MM-YYYY'), 'SUNDAY') FROM DUAL;
-- 01-NOV-26
SELECT ADD_MONTHS(TO_DATE('29-02-1996','DD-MM-YYYY'), 12) FROM DUAL;
-- 28-FEB-97
